  }
}

function mouseReleased() {
  if (!draggingCard) return;
  let dropped = false;
  for (let i = 0; i < slots.length; i++) {
    let s = slots[i];
    if (overRect(draggingCard, s.x, s.y, s.w, s.h) && s.value === null) {
      s.value = draggingCard.value;
      draggingCard.x = s.x;
      draggingCard.y = s.y - 38;
      draggingCard.placed = true;
      dropped = true;
      updateState();
      break;
    }
  }
  if (!dropped) {
    draggingCard.x = draggingCard.homeX;
    draggingCard.y = draggingCard.homeY;
  }
  draggingCard = null;
}

function checkAnswer() {
  isChecked = true;
  if (placedAngle1 === 48 && placedAngle2 === 67 && missingAngleValue === 65) {
    isSolved = true;
    feedbackMsg = 'Harika! Önce topladın, sonra 180°’den çıkardın.';
  } else {
    feedbackMsg = 'Önce 48° ve 67° kartlarını yerleştir. Sonra 180°’den çıkarıp eksik açıyı bul.';
  }
}

function updateState() {
  placedAngle1 = slots[0].value;
  placedAngle2 = slots[1].value;
  missingAngleValue = slots[2].value;
  sumOfGivenAngles = 0;
  if (placedAngle1 !== null) sumOfGivenAngles += placedAngle1;
  if (placedAngle2 !== null) sumOfGivenAngles += placedAngle2;
  if (placedAngle1 !== null && placedAngle2 !== null && missingAngleValue === null) {
    feedbackMsg = 'İyi! Şimdi eksik açıyı 180°’ye tamamla.';
  }
  if (placedAngle1 !== null && placedAngle2 !== null) {
    angleCards[2].homeX = 398;
    angleCards[2].homeY = 150;
  }
}

function hitButton(x, y, w, h) {
  return mouseX >= x && mouseX <= x + w && mouseY >= y && mouseY <= y + h;
}

function hitCard(c) {
  return mouseX >= c.x && mouseX <= c.x + c.w && mouseY >= c.y && mouseY <= c.y + c.h;
}

function overRect(obj, x, y, w, h) {
  return obj.x + obj.w * 0.5 >= x && obj.x + obj.w * 0.5 <= x + w && obj.y + obj.h * 0.5 >= y && obj.y + obj.h * 0.5 <= y + h;
}

function touchStarted() {
  mousePressed();
  return false;
}

function touchEnded() {
  mouseReleased();
  return false;
}

let cards = [];
let slots = [];
let buttons = [];
let feedbackMsg = 'Kartları sürükle.';
let placedAngles = [];
let placedSum = 0;
let missingAngle = null;
let isChecked = false;
let completed = false;
let activeCard = null;

function setup() {
  createCanvas(560, 340);
  textFont('sans-serif');
  initializeGame();
}

function initializeGame() {
  resetGame();
}

function resetGame() {
  cards = [
    { id: 50, x: 396, y: 96, w: 56, h: 34, homeX: 396, homeY: 96, placed: false },
    { id: 60, x: 462, y: 96, w: 56, h: 34, homeX: 462, homeY: 96, placed: false }
  ];
  slots = [{ x: 86, y: 120, w: 110, h: 56, angle: null }, { x: 208, y: 120, w: 110, h: 56, angle: null }];
  buttons = [
    { label: 'Kontrol', x: 404, y: 154, w: 112, h: 30 },
    { label: 'Sıfırla', x: 404, y: 192, w: 112, h: 30 }
  ];
  feedbackMsg = 'Kartları sürükle.';
  placedAngles = [];
  placedSum = 0;
  missingAngle = null;
  isChecked = false;
  completed = false;
  activeCard = null;
}

function draw() {
  background(248);
  drawTitle();
  drawPlayArea();
  drawControls();
  drawFeedback();
  updateState();
}

function drawTitle() {
  fill(30);
  noStroke();
  textSize(16);
  textAlign(LEFT, CENTER);
  text('Açı Topla, Eksik Köşeyi Bul', 18, 30);
}

function drawPlayArea() {
  fill(255);
  stroke(210);
  rect(16, 56, 360, 220, 10);

  // triangle
  noFill();
  stroke(60);
  strokeWeight(2);
  triangle(86, 220, 186, 90, 286, 220);
  strokeWeight(1);

  // angle target slots
  for (let s of slots) {
    fill(250);
    stroke(180);
    rect(s.x, s.y, s.w, s.h, 8);
    noStroke();
    fill(100);
    textSize(13);
    textAlign(CENTER, CENTER);
    text(s.angle === null ? 'Yerleştir' : s.angle + '°', s.x + s.w / 2, s.y + s.h / 2);
  }

  // sum bar
  fill(240);
  stroke(210);
  rect(58, 192, 250, 34, 8);
  noStroke();
  fill(40);
  textSize(13);
  textAlign(LEFT, CENTER);
  text('Toplam: ' + placedSum + '° / 180°', 70, 209);

  if (missingAngle !== null) {
    fill(20, 120, 60);
    textAlign(CENTER, CENTER);
    textSize(18);
    text('Eksik açı: ' + missingAngle + '°', 186, 99);
  } else {
    fill(120);
    textAlign(CENTER, CENTER);
    textSize(12);
    text('Toplamı 180° yap', 186, 99);
  }

  for (let c of cards) {
    fill(c.placed ? color(220, 245, 230) : color(255, 236, 210));
    stroke(120);
    rect(c.x, c.y, c.w, c.h, 8);
    noStroke();
    fill(30);
    textSize(16);
    textAlign(CENTER, CENTER);
    text(c.id + '°', c.x + c.w / 2, c.y + c.h / 2);
  }
}

function drawControls() {
  fill(255);
  stroke(210);
  rect(384, 56, 160, 220, 10);
  fill(40);
  noStroke();
  textAlign(LEFT, TOP);
  textSize(13);
  text('Amaç:
İki açıyı topla.', 398, 70);
  for (let b of buttons) {
    fill(70, 130, 220);
    rect(b.x, b.y, b.w, b.h, 8);
    fill(255);
    textAlign(CENTER, CENTER);
    textSize(14);
    text(b.label, b.x + b.w / 2, b.y + b.h / 2);
  }
}

function drawFeedback() {
  fill(245);
  stroke(210);
  rect(16, 284, 528, 44, 10);
  noStroke();
  fill(30);
  textAlign(LEFT, CENTER);
  textSize(14);
  text(feedbackMsg, 28, 306, 500, 28);
}

function updateState() {
  placedAngles = [];
  placedSum = 0;
  for (let s of slots) {
    if (s.angle !== null) {
      placedAngles.push(s.angle);
      placedSum += s.angle;
    }
  }
  missingAngle = placedSum > 0 ? 180 - placedSum : null;
  completed = placedSum === 110;
}

function mousePressed() {
  for (let b of buttons) {
    if (inside(mouseX, mouseY, b.x, b.y, b.w, b.h)) {
      if (b.label === 'Kontrol') {
        isChecked = true;
        if (completed) {
          feedbackMsg = 'Harika! 50° + 60° = 110°. Eksik açı 70°.';
        } else {
          feedbackMsg = 'Henüz tamam değil. 50° ve 60° kartlarını yerleştir.';
        }
      } else {
        initializeGame();
      }
      return;
    }
  }

  for (let i = cards.length - 1; i >= 0; i--) {
    let c = cards[i];
    if (inside(mouseX, mouseY, c.x, c.y, c.w, c.h)) {
      activeCard = c;
      c.dragOffX = mouseX - c.x;
      c.dragOffY = mouseY - c.y;
      return;
    }
  }
}

function mouseDragged() {
  if (activeCard) {
    activeCard.x = mouseX - activeCard.dragOffX;
    activeCard.y = mouseY - activeCard.dragOffY;
  }
}

function mouseReleased() {
  if (!activeCard) return;
  let placed = false;
  for (let s of slots) {
    if (dist(activeCard.x + activeCard.w / 2, activeCard.y + activeCard.h / 2, s.x + s.w / 2, s.y + s.h / 2) < 45 && s.angle === null) {
      s.angle = activeCard.id;
      activeCard.placed = true;
      activeCard.x = s.x + 27;
      activeCard.y = s.y + 11;
      placed = true;
      feedbackMsg = 'Güzel! Şimdi diğer açıyı ekle.';
      break;
    }
  }
  if (!placed) {
    activeCard.x = activeCard.homeX;
    activeCard.y = activeCard.homeY;
    activeCard.placed = false;
    feedbackMsg = 'Kartı kutunun üstüne bırak.';
  }
  activeCard = null;
}

function inside(px, py, x, y, w, h) {
  return px >= x && px <= x + w && py >= y && py <= y + h;
}
